(()=>{'use strict';
const D=window.COURSE_DATA;
const $=q=>document.querySelector(q),$$=q=>Array.from(document.querySelectorAll(q));
const dict=Object.fromEntries(D.concepts.map(c=>[c.id,c]));
const orderedTopics=Object.keys(D.chapters).flatMap(ch=>D.concepts.filter(c=>String(c.ch)===ch));
const chapterTopics=ch=>orderedTopics.filter(c=>String(c.ch)===String(ch));
const topicPosition=id=>orderedTopics.findIndex(c=>c.id===id);
const topicComplete=ch=>chapterTopics(ch).filter(c=>P.topicDone[c.id]).length;

const read=()=>{try{return JSON.parse(localStorage.getItem('rs-2026-progress'))||{}}catch{return {}}};
const P=Object.assign({checks:{},quiz:{},notes:{},reveals:{},saved:{},exam:{},settings:{},topicDone:{}},read());P.topicDone ||= {};
function persist(){try{localStorage.setItem('rs-2026-progress',JSON.stringify(P))}catch{toast('Browser storage is unavailable; export your progress.')}}
let ui={view:'dashboard',lesson:null,filter:'all',chapter:'5',search:'',formulaSearch:'',practicePhase:'midterm',lab:'reliability',month:'2026-10',timer:'',expParams:{},testSubmitted:false};
const today=(()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`})(), now=()=>new Date(), dateFmt=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',weekday:'short'}), numFmt=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateDays=(a,b)=>Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000);
const pct=(x,y)=>y?Math.round(100*x/y):0;
const checks=['Recall yesterday’s key idea without looking at notes','Understand the concept and draw a mental model','Explain and interpret every formula symbol','Follow the worked engineering example','Answer the checkpoint quizzes without notes','Attempt all independent exercises, then check solutions','Summarize mistakes and complete the exit ticket'];
const dayCheck=l=>checks.filter((_,i)=>P.checks[l.id+'-'+i]).length;
const qAnswered=l=>l.topics.filter(id=>P.quiz[l.id+'-'+id]!==undefined).length;
const isDone=l=>l.kind==='exam'?!!P.checks[l.id+'-exam']:dayCheck(l)>=6;
const lessons=D.lessons.filter(x=>x.kind!=='exam');
const doneCount=()=>lessons.filter(isDone).length;
const progress=pct(doneCount(),lessons.length);
const NEXT=()=>lessons.find(l=>l.date===today)||lessons.find(l=>l.date>today&&!isDone(l))||lessons.find(l=>!isDone(l))||lessons.at(-1);
const badge=(txt,kind='')=>`<span class="pill ${kind}">${esc(txt)}</span>`;
const button=(s,action,id,cls='secondary')=>`<button class="button ${cls} small" data-action="${action}" data-id="${esc(id)}">${s}</button>`;
function route(view,id=null){ui.view=view;ui.lesson=id;if(view==='topic'&&dict[id])ui.chapter=String(dict[id].ch);const dest=`#${view}${id?'/'+id:''}`;if(location.hash!==dest)history.pushState({},'',dest);render(true)}
function toast(s){const x=$('#toast');x.textContent=s;x.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>x.classList.remove('show'),2800)}
function math(){if(window.MathJax?.typesetPromise){window.MathJax.typesetClear?.();window.MathJax.typesetPromise([$('#main-content')]).catch(e=>console.warn('Math render',e))}else setTimeout(()=>{if(window.MathJax?.typesetPromise)math()},350)}
const fmtMath=s=>`\\[${esc(s)}\\]`;
const fmtInline=s=>`\\(${s}\\)`;
const srcCh=ch=>`<a href="#coverage" data-action="nav" data-id="coverage">Textbook Chapter ${ch} ↗</a>`;
function render(scroll=false){let html='';const oldScroll=window.scrollY;
 switch(ui.view){case 'lessons':html=pageLessons();break;case 'review':html=pageReview();break;case 'lesson':html=pageLesson();break;case 'topic':html=pageTopic();break;case 'planner':html=pagePlanner();break;case 'practice':html=pagePractice();break;case 'formulas':html=pageFormulas();break;case 'lab':html=pageLab();break;case 'coverage':html=pageCoverage();break;default:ui.view='dashboard';html=pageDashboard()}
 $('#main-content').innerHTML=html;$('#breadcrumb').innerHTML=ui.view==='topic'&&dict[ui.lesson]?`My learning space <span> / Chapter ${dict[ui.lesson].ch} / ${esc(dict[ui.lesson].title)}</span>`:`My learning space <span> / ${esc(({dashboard:'Overview',lessons:'Course chapters',lesson:'Study session',topic:'Topic lesson',review:'Chapter 5 sprint review',planner:'Study plan',practice:'Exam practice',formulas:'Formula bank',lab:'Interactive lab',coverage:'Source coverage'})[ui.view])}</span>`;
 $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===(['lesson','topic'].includes(ui.view)?'lessons':ui.view)));
 $('#sidebar').classList.remove('open');$('#mobile-overlay').classList.remove('open');
 if(scroll)window.scrollTo({top:0,behavior:'instant'});else window.scrollTo({top:oldScroll,behavior:'instant'});
 math();if(ui.view==='lab')drawLab();}
function pageDashboard(){let next=NEXT(), remainM=Math.max(0,dateDays(today,D.meta.midterm)), remainF=Math.max(0,dateDays(today,D.meta.final));
return `<section class="hello-row"><div><div class="eyebrow">YOUR LEARNING DASHBOARD</div><h1>Good to see you, Kanu! <span class="greeting-deco">you've got this ✨</span></h1><p class="sub">A focused, structured path from first principles to confident exam solutions.</p></div><div class="illustration" aria-hidden="true">📚 🌱</div></section>
<section class="hero"><div class="hero-content"><span class="hero-tag">✦ YOUR NEXT STEP · ${esc(dateFmt(next.date))}</span><h2>${esc(next.title)}</h2><p>One two-hour session at a time. Understand the physics, learn the method, solve a real problem, and practice until it's yours.</p><button class="button" data-action="open-lesson" data-id="${next.id}">Open today's study session <span>→</span></button> <button class="button ghost" data-action="go-ch5" data-id="5">Browse Chapter 5 lessons →</button><div class="next-topics">${next.topics.slice(0,3).map(t=>`<span>${esc(dict[t].title)}</span>`).join('')}</div></div><div class="hero-visual"><div class="hero-graph"><div class="spark-caption"><span>YOUR KNOWLEDGE CURVE</span><span class="stars">✦ ✦ ✦</span></div><svg viewBox="0 0 240 104" aria-hidden="true"><defs><linearGradient id="heroGrad" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#9080ee" stop-opacity=".26"/><stop offset="1" stop-color="#9080ee" stop-opacity="0"/></linearGradient></defs><path d="M4 95 C30 83 36 93 61 72S105 67 128 46 168 64 193 22 221 27 236 7L236 103H4Z" fill="url(#heroGrad)"/><path d="M4 95 C30 83 36 93 61 72S105 67 128 46 168 64 193 22 221 27 236 7" fill="none" stroke="#9585e9" stroke-width="4" stroke-linecap="round"/><circle cx="236" cy="7" r="5" fill="#7667e9" stroke="white" stroke-width="3"/></svg><b>Progress is powerful.</b><div class="spark-caption"><span>show up</span><span>get stronger →</span></div></div><span class="tiny-sticker">🌟 one day closer</span></div></section>
<div class="metric-grid"><div class="metric"><span class="metric-icon">⏳</span><div><b>${remainM}</b><small>Calendar days until Midterm 2</small></div></div><div class="metric"><span class="metric-icon">✓</span><div><b>${doneCount()} <span class="muted" style="font-size:14px">/ ${lessons.length}</span></b><small>Full 120-minute sessions completed</small></div></div><div class="metric"><span class="metric-icon">🎓</span><div><b>${remainF}</b><small>Calendar days until the final</small></div></div></div>
<div class="cards cols-2"><section class="card"><div class="section-heading" style="margin:0 0 16px"><h2>Up next on your path 🗓️</h2><button class="link" data-action="nav" data-id="planner">Full plan →</button></div><div class="day-list">${(D.lessons.filter(l=>l.date>=today).length?D.lessons.filter(l=>l.date>=today):D.lessons.slice(-6)).slice(0,6).map(l=>dayItem(l)).join('')}</div></section><section class="card"><div class="section-heading" style="margin:0 0 16px"><h2>Your study momentum 💜</h2></div><div style="display:flex;align-items:center;gap:22px;margin:10px 0 20px"><div class="ring" style="--angle:${progress}%"><div class="ring-inner"><b>${progress}%</b><small>complete</small></div></div><div style="flex:1"><b style="display:block;margin-bottom:7px">Build it, step by step.</b><p class="muted small">Tick off your understanding and exercises in every lesson. Your progress stays on this device.</p>${button('Browse lessons →','nav','lessons','ghost')}</div></div><div class="deadline-cards"><button class="deadline" data-action="exam" data-id="midterm" style="text-align:left;cursor:pointer"><small>FIRST MILESTONE</small><b>Nov 5</b><span class="date">75-minute Midterm 2<br>Ch. 5–7 requested</span></button><button class="deadline" data-action="exam" data-id="final" style="text-align:left;cursor:pointer"><small>SECOND MILESTONE</small><b>Dec 18</b><span class="date">150-minute Final exam<br>9:00 AM Central</span></button></div></section></div><div class="notice"><span>ⓘ</span><div><strong>Scope note:</strong> Kanu requested Chapters 5–7 for Midterm 2. The supplied syllabus verifies exam dates but not the detailed assessed chapters. The final's nine-chapter path is deliberately comprehensive, pending faculty confirmation.</div></div>`}
function dayItem(l){return `<button class="day-item" data-action="${l.kind==='exam'?'exam':'open-lesson'}" data-id="${l.kind==='exam'?(l.id==='EXAM-M'?'midterm':'final'):l.id}"><div class="date-box"><b>${new Date(l.date+'T12:00:00').getDate()}</b><span>${new Date(l.date+'T12:00:00').toLocaleDateString('en-US',{month:'short'})}</span></div><div class="day-copy"><b>${esc(l.title)}</b><small>${l.kind==='exam'?'Exam day':`Session ${l.id} · 120 min · Ch. ${l.chapters.join(', ')}`}</small></div>${isDone(l)?badge('✓ Done','mint'):'<span class="day-arrow">›</span>'}</button>`}
function pageLessons(){
 const term=ui.search.trim().toLowerCase();
 const activeCh=ui.chapter==='all'?'5':String(ui.chapter);
 const chItems=chapterTopics(activeCh).filter(c=>!term||(`${c.title} ${c.id} ${c.deep?.name} ${c.refs}`).toLowerCase().includes(term));
 const completed=topicComplete(activeCh), all=chapterTopics(activeCh), firstUnfinished=all.find(c=>!P.topicDone[c.id])||all[0];
 const related=lessons.filter(l=>l.chapters.includes(Number(activeCh))&&(ui.filter==='all'||l.phase===ui.filter));
 return `<div class="library-heading"><div><div class="eyebrow">A CLEAR PATH · CHAPTER → TOPIC → FULL LESSON</div><h1>Course chapters 📖</h1><p class="sub">Choose a chapter, then read one topic at a time. Your dated study sessions remain in the planner — they are not the lessons themselves.</p></div>${button('⚡ Chapter 5 quick recall','nav','review','ghost')}</div>
 <div class="library-shell">
  <aside class="chapter-rail" aria-label="Chapter selection"><div class="small-label rail-label">CHOOSE A CHAPTER</div>
   ${Object.entries(D.chapters).map(([ch,title])=>{const all=chapterTopics(ch),n=topicComplete(ch);return `<button class="chapter-rail-item ${activeCh===ch?'active':''}" data-action="chapter-filter" data-id="${ch}" ${activeCh===ch?'aria-current="true"':''}><span class="chapter-rail-number">${ch}</span><span class="chapter-rail-text"><b>Chapter ${ch}</b><small>${esc(title)}</small><span class="rail-meter"><i style="width:${pct(n,all.length)}%"></i></span></span><span class="rail-count">${n}/${all.length}</span></button>`}).join('')}
  </aside>
  <section class="library-primary"><div class="chapter-overview"><div class="eyebrow">CHAPTER ${activeCh} OF 9 · ${[5,6,7].includes(Number(activeCh))?'MIDTERM STUDY PRIORITY':'FOUNDATION / FINAL TRACK'}</div><h2>${esc(D.chapters[activeCh])}</h2><p>${all.length} topics in sequence. Study the explanation first, solve questions before revealing solutions, and mark a topic complete only when you can explain the method without notes.</p>
   <div class="chapter-overview-footer"><div><strong>${completed} of ${all.length} topics mastered</strong><div class="progress-track" role="progressbar" aria-label="Chapter ${activeCh} completion" aria-valuenow="${completed}" aria-valuemax="${all.length}"><div class="progress-fill" style="width:${pct(completed,all.length)}%"></div></div></div>${firstUnfinished?button(completed?'Review this chapter →':'Continue learning →','open-topic',firstUnfinished.id):''}</div>
  </div>
  <div class="topic-index-head"><div><h3>Topic lessons, in order</h3><p class="small muted">The topics below open as full-length lessons. Progress is stored in this browser.</p></div><input id="lesson-search" class="search" aria-label="Search topics" placeholder="⌕ Find a topic in this chapter" value="${esc(ui.search)}"></div>
  <div class="topic-index">${chItems.map((c)=>{const i=all.findIndex(x=>x.id===c.id);return `<button class="topic-index-item" data-action="open-topic" data-id="${esc(c.id)}"><span class="topic-index-number">${activeCh}.${String(i+1).padStart(2,'0')}</span><span class="topic-index-info"><strong>${esc(c.title)}</strong><small>${esc(c.deep?.name||'Engineering concept')} · Definitions, annotated formula, worked examples, guided practice</small></span><span class="topic-index-action">${P.topicDone[c.id]?'✓ Mastered':'Read lesson →'}</span></button>`}).join('')||'<div class="empty-state">No topics match. Try another search term.</div>'}</div>
  <details class="chapter-sessions" style="margin-top:25px"><summary>See scheduled two-hour study sessions (${related.length})</summary><p class="small muted">These are optional teaching plans combining multiple topics. For focused reading, use the topic lessons above.</p><div class="lesson-grid">${related.map(l=>`<button class="lesson-tile" data-action="open-lesson" data-id="${l.id}"><div class="tile-top">${badge(l.id)}${badge('Chapter '+l.chapters.join(', '))}</div><strong>${esc(l.title)}</strong><small>${esc(dateFmt(l.date))} · ${l.duration} minutes</small><div class="tile-bottom"><span>${dayCheck(l)}/7 steps done</span><span>Open study plan →</span></div></button>`).join('')}</div></details>
  </section>
 </div>`;
}
function pageReview(){const r=D.chapterReview['5'];return `<div class="hello-row"><div><div class="eyebrow">CHAPTER 5 · RAPID RECALL ONLY</div><h1>Six-minute recap. Then problems. ⚡</h1><p class="sub">Keep review deliberately short, just as requested. Explanations are hidden unless you need them, and the full chapter lessons remain available.</p></div><div class="illustration">🧠</div></div><div class="notice"><span>⏱</span><div><strong>Practice-first routine:</strong> 6 minutes of answer-from-memory prompts, 30–75 minutes of independent engineering problems, 10 minutes correcting mistakes. Re-read the deep lesson only for a diagnosed gap; repeat one failed problem 24 hours later.</div></div><div class="card"><div class="eyebrow">THE DECISION PATH</div><p>${esc(r.decision)}</p></div><section class="card"><h2>Active recall — no notes first</h2><p class="small muted">State your answer aloud or on paper, then open the explanation. The act of retrieving builds exam-ready memory better than rereading.</p>${r.prompts.map(([question,answer],i)=>`<details class="review-question"><summary><b>${i+1}.</b> ${esc(question)}</summary><p>${esc(answer)}</p></details>`).join('')}</section><section class="card"><h2>Independent Chapter 5 exam drills ✍️</h2><p class="small muted">Predict the method from the wording BEFORE any calculation. Try these without notes. Worked solutions stay folded until you're ready.</p>${r.practiceIds.map((id,i)=>{const c=dict[id];return `<details class="review-question"><summary><b>Problem ${i+1} · ${esc(c.title)}</b> — ${esc(c.deep.exam_problem)}</summary><div class="worked"><b>Worked solution and rationale:</b> ${esc(c.deep.exam_solution)}</div><div style="margin-top:12px">${button('Open full teaching lesson','topic-practice',id,'ghost')}</div></details>`}).join('')}</section><div class="chiprow">${button('Study Chapter 5 deeply →','go-ch5','5')}${button('Timed exam practice →','nav','practice','ghost')}${button('Formula bank →','nav','formulas','ghost')}</div>`}
function pageLesson(){const l=D.lessons.find(x=>x.id===ui.lesson);if(!l)return pageLessons();const topics=l.topics.map(id=>dict[id]).filter(Boolean);const totalQuiz=qAnswered(l);let clock=[['00–10','Warm-up retrieval: explain yesterday’s method, units and assumptions without notes.'],['10–30','Build intuition: use diagrams and the chapter map to identify what the problem asks.'],['30–50','Derive and decode the formulas; annotate parameters, conditions and table values.'],['50–70','Guided worked engineering example; pause before each computation to predict the next step.'],['70–85','Mid-lesson checkpoint: solve the multiple-choice questions with no hints.'],['85–105','Independent exam-style exercises and a relevant interactive lab experiment.'],['105–120','Check answers, log errors, recap the decision rule, assign next-day retrieval.']];
return `${lessonPager(l,"top")}<div class="lesson-head"><button class="back-btn" data-action="nav" data-id="lessons">← Back to all lessons</button>${badge(l.phase==='midterm'?'Midterm 2 sprint':'Final study track',l.phase==='midterm'?'peach':'')}</div><div class="eyebrow">${l.id} · ${esc(dateFmt(l.date))} · ${l.duration} MINUTES</div><h1 class="lesson-title">${esc(l.title)}</h1><div class="lesson-meta">${badge('⏱ 2-hour guided session','blue')}${badge('📚 Chapters '+l.chapters.join(', '))}${badge('✏ '+topics.length+' concept workshops','mint')}${badge('✓ '+totalQuiz+'/'+topics.length+' quizzes answered','peach')}</div><div class="notice" style="margin-top:0"><span>🎯</span><div><strong>Learning objective:</strong> Explain the physical situation in plain language, identify which method applies, write the correct formula with assumptions, solve a numerical engineering problem, and interpret the result. ${l.phase==='final'?'The final scope is provisional until the instructor confirms it.':''}</div></div>
<div class="learning-layout"><div class="learning-main"><section class="card"><h2 style="margin-bottom:6px">Your 120-minute run of show ⏱️</h2><p class="muted small">Use these teaching blocks to fill the full two hours: stop for questions, show calculations by hand, and let Kanu attempt each problem.</p><div class="session-table">${clock.map(([t,what])=>`<div class="session-row"><div class="time">${t} min</div><div>${what}</div></div>`).join('')}</div></section><section class="card" style="background:var(--lav);border-color:#dfd7fa"><div class="eyebrow">TODAY'S TOPICS</div><div class="chiprow" style="margin-top:9px">${topics.map((c,i)=>`<button class="filter-btn" data-action="open-topic" data-id="${c.id}">${i+1}. ${esc(c.title)} · full lesson →</button>`).join('')}</div><p class="small muted" style="margin:13px 0 0">For each topic: concept → intuition → formula → model example → independent problem → embedded quiz → experiment.</p></section>${topics.map((c,i)=>topicCard(c,l,i)).join('')}<section class="card"><h2>Lesson exit ticket 🌼</h2><p class="muted small">Before marking this lesson complete, explain the method in a 60-second teach-back, solve one question without looking, and write what still feels uncertain.</p><div class="practice-box"><b>Retrieval prompts</b><p>1. How do you recognize which of today's methods the exam problem requires?<br>2. What conditions must hold for the main equation?<br>3. Which units and limits should your numerical result satisfy?<br>4. What would make this answer physically unreasonable?</p></div><div class="topic-title">Your lesson notes & mistake log</div><textarea class="note-area" data-note="${l.id}" placeholder="What clicked today? Which calculation was hard? What should we revisit?">${esc(P.notes[l.id]||'')}</textarea><div style="margin-top:12px;display:flex;gap:9px;flex-wrap:wrap">${button('Print this lesson','print','')} ${button('Return to calendar →','nav','planner','ghost')}</div></section></div>
<aside class="lesson-aside"><div class="card"><h3>Today's checklist 💜</h3><p class="muted small">${dayCheck(l)} of 7 completed</p><div class="progress-track" style="margin:13px 0 19px"><div class="progress-fill" style="width:${pct(dayCheck(l),7)}%"></div></div><div class="study-steps">${checks.map((s,i)=>`<label class="checkline"><input type="checkbox" data-check="${l.id}-${i}" ${P.checks[l.id+'-'+i]?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div><p class="small muted" style="margin:18px 0 0">Quizzes are graded automatically; checklist items are self-assessed.</p></div><div class="card"><div class="small-label">Focus session timer</div><div class="timer" id="session-timer">02:00:00</div><div class="timer-controls"><button class="button small" data-action="timer-start" data-id="${l.id}" id="timer-toggle">Start</button>${button('Reset','timer-reset',l.id,'ghost')}</div><p class="small muted" style="margin:9px 0 0">Optional 120-minute countdown. It does not auto-submit anything.</p></div><div class="card"><h3>Study resources</h3><div class="source-row"><a class="source-link" href="https://drive.google.com/drive/folders/1ozobGt-ke1pkCaYuZsxjTGP9rdbmeQ5a" target="_blank" rel="noopener noreferrer">📁 Kanu's Drive folder ↗</a><a class="source-link" href="https://drive.google.com/file/d/1148vFiqdBaMrc8knX89JLGKiayerEoQp/view" target="_blank" rel="noopener noreferrer">📖 Textbook ↗</a>${l.chapters.includes(5)?'<a class="source-link" href="https://drive.google.com/file/d/1wllHplISD8jUxm7_puCKHY-l6EvmooBy/view" target="_blank" rel="noopener noreferrer">📑 Ch. 5 faculty slides ↗</a>':''}</div></div></aside></div>${lessonPager(l,"bottom")}`}
function topicCard(c,l,i){const qid=l.id+'-'+c.id,stored=P.quiz[qid],key='reveal:'+qid;return `<article class="card topic-card" id="topic-${c.id}"><button class="topic-header" data-action="toggle-topic" data-id="${c.id}" aria-expanded="${i===0?'true':'false'}"><div><span class="small-label">CONCEPT WORKSHOP ${i+1} · CHAPTER ${c.ch}</span><strong>${esc(c.title)}</strong><small>${esc(c.refs)}</small></div><span class="chev">⌄</span></button><div class="topic-body ${i===0?'':'hidden'}" id="body-${c.id}"><div class="topic-title">① Understand it simply</div><p>${esc(c.plain)}</p><div class="topic-title">② What the engineer should notice</div><p>${esc(c.why)}</p><div class="deep-panel"><div class="eyebrow">THE DEEP DIVE — BUILD UNDERSTANDING</div><div class="topic-title">The physical intuition</div><p>${esc(c.deep?.intuition||c.why)}</p><div class="topic-title">When it works, and when it fails</div><p>${esc(c.deep?.assumptions||'Identify the model assumptions and verify their validity.')}</p></div><div class="formula-panel"><div class="formula-label">③ ${esc(c.deep?.name||'ENGINEERING EQUATION')}</div><div class="math">${fmtMath(c.formula)}</div><div class="formula-explanation"><b>What every symbol means</b><p>${esc(c.deep?.symbols||'Define all variables and model parameters before substituting.')}</p><b>Where this relation comes from / how to apply it</b><p>${esc(c.deep?.derivation||c.why)}</p></div></div><div class="memory-panel"><strong>🧠 Understanding-based memory hook</strong><p>${esc(c.deep?.memory||'Recognize the model, explain why it applies, derive it and solve an independent variation.')}</p></div><div class="topic-title">④ Worked engineering example</div><div class="worked">${esc(c.worked)}</div><div class="practice-box"><div class="topic-title" style="margin-top:0">⑤ Your turn · show all steps</div><p>${esc(c.practice)}</p>${button(P.reveals[key]?'Hide worked answer':'Reveal worked answer','reveal',key,'ghost')}<div class="reveal ${P.reveals[key]?'open':''}"><b>Model answer:</b> ${esc(c.answer)}<br><span style="opacity:.75">After checking, explain the numerical outcome and its units in one sentence.</span></div></div><div class="practice-box"><div class="topic-title">⑥ Extra deep-dive exam variation</div><p>${esc(c.deep?.exam_problem||c.practice)}</p><details class="review-question"><summary>Reveal full worked reasoning</summary><p>${esc(c.deep?.exam_solution||c.answer)}</p></details></div><div class="drill-stack"><h4>⑦ DEEP PRACTICE · TWO ADDITIONAL EXAM CHALLENGES</h4><p class="small muted">Work on paper first. Use the prompt to set up the model and annotate assumptions before revealing solutions.</p>${(c.drills||[]).map((dr,j)=>`<details class="drill-card"><summary>Challenge ${j+1} · ${esc(dr.title)}</summary><div class="drill-content"><p>${esc(dr.problem)}</p><button class="solution-toggle" data-action="drill-answer">Show worked solution ↓</button><div class="solution-text"><b>Answer / reasoning:</b> ${esc(dr.solution)}</div></div></details>`).join('')}</div><div class="quiz-box"><div class="topic-title" style="margin-top:0">⑧ Mid-lesson quick quiz</div><h4>${esc(c.question)}</h4>${c.options.map((o,j)=>{let cl=stored!==undefined?(j===stored?(j===c.correct?'selected-correct':'selected-wrong'):''):'';return `<button class="quiz-opt ${cl}" data-action="quiz" data-id="${qid}" data-choice="${j}" aria-pressed="${stored===j}"><span style="display:inline-grid;place-items:center;width:25px;height:25px;border-radius:8px;background:var(--surf2);margin-right:11px;font-size:10px;font-weight:900">${'ABC'[j]}</span>${esc(o)}</button>`}).join('')}${stored!==undefined?`<div class="quiz-feedback" style="color:${stored===c.correct?'var(--green)':'#be6559'}">${stored===c.correct?'✓ Correct!':'↻ Try explaining what makes the correct method different.'} ${esc(c.trap)}</div>`:''}</div><div class="chiprow" style="margin-top:15px">${button('◈ Experiment with this idea','open-lab',c.sim||'reliability')}${button(P.saved[c.id]?'★ Saved formula':'☆ Save formula','save-formula',c.id,'ghost')}</div><div class="topic-source">SOURCE ALIGNMENT · ${esc(c.refs)} · This teaching explanation and its practice question are original, not a reproduction of the textbook.</div></div></article>`}
function readerPager(c,placement='bottom'){
 const i=topicPosition(c.id),prev=orderedTopics[i-1],next=orderedTopics[i+1];
 return `<nav class="reader-pager ${placement==='top'?'pager-top':''}" aria-label="Topic sequence"><div class="pager-cell">${prev?`<button class="pager-button" data-action="open-topic" data-id="${prev.id}" aria-label="Previous lesson: ${esc(prev.title)}"><span class="pager-arrow">← Previous lesson</span><strong>${esc(prev.title)}</strong><small>Chapter ${prev.ch}</small></button>`:'<span class="pager-empty">Beginning of the course</span>'}</div><div class="pager-count">Lesson ${i+1} of ${orderedTopics.length}</div><div class="pager-cell">${next?`<button class="pager-button next" data-action="open-topic" data-id="${next.id}" aria-label="Next lesson: ${esc(next.title)}"><span class="pager-arrow">Next lesson →</span><strong>${esc(next.title)}</strong><small>Chapter ${next.ch}</small></button>`:'<span class="pager-empty">You reached the final topic 🎉</span>'}</div></nav>`
}
function pageTopic(){
 const c=dict[ui.lesson];if(!c)return pageLessons();
 const chapter=String(c.ch),chapterList=chapterTopics(chapter),inChapter=chapterList.findIndex(x=>x.id===c.id),en=window.RS_DEEP_LESSONS?.[c.id],qid='reader-'+c.id,stored=P.quiz[qid],revealKey='reveal:reader-'+c.id;
 const section=(name,body)=>`<section class="reader-section"><h2>${esc(name)}</h2><p>${esc(body)}</p></section>`;
 return `<div class="reader-top"><button class="back-btn" data-action="find-chapter" data-id="${chapter}">← Chapter ${chapter} overview</button><div class="reader-top-badges">${badge('Chapter '+chapter,'blue')}${badge('Topic '+(inChapter+1)+' / '+chapterList.length,'mint')}${P.topicDone[c.id]?badge('✓ Mastered','mint'):badge('In progress')}</div></div>
 <div class="reader-shell"><aside class="reader-rail" aria-label="Chapter ${chapter} topics"><div class="small-label">CHAPTER ${chapter} · CONTENTS</div><h3>${esc(D.chapters[chapter])}</h3><div class="reader-rail-meter">${topicComplete(chapter)} of ${chapterList.length} topics mastered<div class="progress-track"><div class="progress-fill" style="width:${pct(topicComplete(chapter),chapterList.length)}%"></div></div></div><button class="reader-rail-toggle" data-action="toggle-reader-outline" aria-expanded="false" aria-controls="reader-outline">Show all ${chapterList.length} chapter topics ▾</button><nav id="reader-outline">${chapterList.map((x,i)=>`<button data-action="open-topic" data-id="${x.id}" class="reader-rail-link ${x.id===c.id?'active':''}" ${x.id===c.id?'aria-current="page"':''}><span>${chapter}.${String(i+1).padStart(2,'0')}</span><b>${esc(x.title)}</b><em>${P.topicDone[x.id]?'✓':''}</em></button>`).join('')}</nav><button class="button ghost small" data-action="find-chapter" data-id="${chapter}">See chapter overview ↗</button></aside>
 <div class="reader-main">${readerPager(c,'top')}
 <article class="reader-article" id="reading-content"><div class="eyebrow">ENGINEERING MASTERCLASS · ${esc(c.refs)}</div><h1>${esc(c.title)}</h1><p class="reader-lede">${esc(en?.goal||c.why)}</p><div class="reader-objectives"><strong>At the end of this lesson, you should be able to</strong><ol><li>Explain what the method measures and when to use it.</li><li>Recognize the model assumptions and define every mathematical symbol.</li><li>Solve and verify a new engineering problem without copying the example.</li></ol></div>
 ${section('01 · Begin with the real engineering question',c.plain)}${section('02 · Why this method matters',c.why)}
 ${en?`<section class="reader-section"><div class="reader-section-label">FOUNDATIONS · READ AND EXPLAIN</div><h2>03 · Build the concept from first principles</h2>${en.explore.map(([h,p])=>`<div class="reader-paragraph"><h3>${esc(h)}</h3><p>${esc(p)}</p></div>`).join('')}</section>`:section('03 · Physical intuition and core reasoning',c.deep?.intuition||c.why)}
 <section class="reader-section formula-focus"><div class="reader-section-label">THE FORMULA, EXPLAINED</div><h2>04 · ${esc(c.deep?.name||'Mathematical model')}</h2><div class="math">${fmtMath(c.formula)}</div><div class="reader-formula-notes"><div><b>Symbols and units</b><p>${esc(c.deep?.symbols||'Name and define each symbol before substitution.')}</p></div><div><b>Derivation / reasoning</b><p>${esc(c.deep?.derivation||c.why)}</p></div><div><b>Assumptions and validity</b><p>${esc(c.deep?.assumptions||c.trap)}</p></div></div></section>
 <section class="reader-section"><h2>05 · Worked engineering problem — step by step</h2><div class="worked reader-worked"><b>Original worked example:</b><p>${esc(c.worked)}</p></div><h3>Reproduce the solution, don't memorize the numbers</h3><ol class="reasoning-steps">${(en?.steps||['Read the physical problem and identify the unknown and units.','Write the governing model, then check that assumptions hold.','Substitute consistent data and calculate carefully.','Interpret the result in engineering language and sanity-check its scale.']).map((x,i)=>`<li><b>Step ${i+1}</b><p>${esc(x)}</p></li>`).join('')}</ol></section>
 <section class="reader-section"><h2>06 · Recognize the question before choosing a formula</h2><div class="memory-panel"><strong>🧠 Decision rule — learn the reason</strong><p>${esc(en?.decision||c.deep?.memory||c.why)}</p></div><div class="reader-callout"><b>Common exam error to avoid</b><p>${esc(c.trap)}</p></div><p>${esc(c.deep?.memory||'Identify conditions, derive the method, and check the answer against physical expectations.')}</p></section>
 <section class="reader-section"><div class="reader-section-label">ACTIVE PRACTICE · DO THE WORK FIRST</div><h2>07 · Solve without looking at the answer</h2><div class="reader-practice"><div class="small-label">GUIDED PROBLEM</div><p>${esc(c.practice)}</p><details class="review-question"><summary>Reveal fully explained solution</summary><p>${esc(c.answer)}</p></details></div><div class="reader-practice"><div class="small-label">EXAM VARIATION</div><p>${esc(c.deep?.exam_problem||c.practice)}</p><details class="review-question"><summary>Reveal worked answer</summary><p>${esc(c.deep?.exam_solution||c.answer)}</p></details></div>${en?`<div class="reader-practice"><div class="small-label">NEW TRANSFER PROBLEM</div><p>${esc(en.challenge[0])}</p><details class="review-question"><summary>Reveal computation and reasoning</summary><p>${esc(en.challenge[1])}</p></details></div>`:''}${(c.drills||[]).map((d,i)=>`<div class="reader-practice"><div class="small-label">INDEPENDENT CHALLENGE ${i+1}</div><p>${esc(d.problem)}</p><details class="review-question"><summary>Reveal solution</summary><p>${esc(d.solution)}</p></details></div>`).join('')}</section>
 <section class="reader-section"><h2>08 · Make the knowledge retrievable</h2><p>Close your notes and answer aloud. If you cannot explain a choice or a sign in your own words, revisit the relevant section before moving on.</p><ol class="reader-recall">${(en?.recall||[c.question,'What assumptions must hold for this formula?','How would you spot an impossible answer?']).map(q=>`<li>${esc(q)}</li>`).join('')}</ol><div class="quiz-box"><h3>Checkpoint quiz</h3><p>${esc(c.question)}</p>${c.options.map((o,j)=>`<button class="quiz-opt ${stored!==undefined&&j===stored?(j===c.correct?'selected-correct':'selected-wrong'):''}" data-action="quiz" data-id="${qid}" data-choice="${j}" aria-pressed="${stored===j}"><span>${'ABC'[j]}.</span> ${esc(o)}</button>`).join('')}${stored!==undefined?`<div class="quiz-feedback">${stored===c.correct?'✓ Correct!':'↻ Review why this choice fails.'} ${esc(c.trap)}</div>`:''}</div></section>
 <section class="reader-section"><h2>09 · Make it yours</h2><p>Explain the lesson in 60 seconds. Write one mistake you must avoid in the exam and one question to revisit tomorrow.</p><textarea class="note-area" data-note="topic-${c.id}" aria-label="Your notes for ${esc(c.title)}" placeholder="My explanation, mistakes and next-day recall...">${esc(P.notes['topic-'+c.id]||'')}</textarea><div class="reader-tools">${button('◈ Explore in the interactive lab','open-lab',c.sim||'reliability','ghost')}${button(P.saved[c.id]?'★ Saved formula':'☆ Save formula','save-formula',c.id,'ghost')}${button('Print or save as PDF','print','', 'ghost')}</div><div class="mastery-gate"><div><strong>${P.topicDone[c.id]?'✓ You marked this topic as mastered':'Can you teach this without notes?'}</strong><p>Mark complete after solving at least one unfamiliar problem and explaining the equation and assumptions.</p></div><button class="button ${P.topicDone[c.id]?'ghost':'secondary'}" data-action="topic-complete" data-id="${c.id}" aria-pressed="${!!P.topicDone[c.id]}">${P.topicDone[c.id]?'Mark for revision':'✓ Mark topic mastered'}</button></div></section>
 <div class="reader-source">${esc(c.refs)} · Original teaching notes and problems. Use the course textbook and faculty slides to confirm official coverage and tables.</div></article>${readerPager(c)}</div></div>`
}
function lessonPager(l,placement){const i=lessons.findIndex(x=>x.id===l.id),prev=lessons[i-1],next=lessons[i+1];return `<nav class="session-pager ${placement==='top'?'pager-top':''}" aria-label="Study-session sequence"><div>${prev?button('← Previous study session · '+prev.id,'open-lesson',prev.id,'ghost'):''}</div><span>Study session ${i+1} / ${lessons.length}</span><div>${next?button('Next study session · '+next.id+' →','open-lesson',next.id):''}</div></nav>`}
function pagePlanner(){const mm=ui.month;let [year,month]=mm.split('-').map(Number),first=new Date(year,month-1,1),len=new Date(year,month,0).getDate(),dow=(first.getDay()+6)%7;let grid=Array.from({length:dow},()=>`<div class="cal-day empty"></div>`);for(let d=1;d<=len;d++){const date=`${year}-${String(month).padStart(2,'0')}-${String(d).padStart(2,'0')}`,l=D.lessons.find(x=>x.date===date);grid.push(l?`<button class="cal-day ${date===today?'today':''} ${l.kind==='exam'?'is-exam':''}" data-action="${l.kind==='exam'?'exam':'open-lesson'}" data-id="${l.kind==='exam'?(l.id==='EXAM-M'?'midterm':'final'):l.id}"><b class="day-num">${d}</b><span class="cal-title">${esc(l.title)}</span>${isDone(l)?'<span class="cal-done">✓ Complete</span>':'<i class="dot"></i>'}</button>`:`<div class="cal-day" style="opacity:.35"><b class="day-num">${d}</b></div>`)}return `<div class="hello-row"><div><div class="eyebrow">TWO MILESTONES · ONE CONSISTENT PLAN</div><h1>Your everyday study plan 🗓️</h1><p class="sub">13 daily sessions before Midterm 2, then 42 daily final-track sessions. Adjust to actual availability.</p></div><div class="illustration">🗓️</div></div><div class="notice"><span>⏱</span><div><strong>Pacing:</strong> Each study-day entry is a full 120-minute lesson, not a promise that tutoring is booked. November 5 and December 18 are actual exam dates from the syllabus. The final coverage plan is provisional.</div></div><div class="section-heading planner-month"><div><div class="eyebrow">CALENDAR VIEW</div><h2>${first.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2></div><div class="chiprow"><button class="filter-btn" data-action="month" data-id="2026-10" ${mm==='2026-10'?'aria-current="true"':''}>October</button><button class="filter-btn" data-action="month" data-id="2026-11">November</button><button class="filter-btn" data-action="month" data-id="2026-12">December</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="cal-weekday">${x}</div>`).join('')}${grid.join('')}</div><div class="section-heading"><h2>Exam checkpoints</h2></div><div class="deadline-cards"><button class="deadline" data-action="exam" data-id="midterm" style="text-align:left"><small>THURSDAY, NOVEMBER 5</small><b>Midterm 2 🎯</b><span class="date">75 minutes · chapter requests 5–7</span></button><button class="deadline" data-action="exam" data-id="final" style="text-align:left"><small>FRIDAY, DECEMBER 18</small><b>Final exam 🎓</b><span class="date">9:00 AM Central · 150 minutes</span></button></div>`}
function pagePractice(){const phase=ui.practicePhase;const ids=phase==='midterm'?D.concepts.filter(x=>[5,6,7].includes(x.ch)):D.concepts;const sampled=phase==='midterm'?['normal_plot','chisq_gof','ks_test','mom','mle','ci_z','ci_t','variance_ci','transform_linear','regression','normal_reliability','form']:['set_events','total_bayes','joint_cov','normal_family','extreme_weibull','ci_t','regression','form','sorm','systems','mc_basics','vrt','correlated_sampling','sample_size','likelihood'];const test=sampled.map(id=>dict[id]).filter(Boolean);const results=test.map(c=>P.exam[phase+'-'+c.id]);const attempted=results.filter(x=>x!==undefined).length,correct=results.filter((x,i)=>x===test[i].correct).length;const submitted=!!P.settings['submitted-'+phase];return `<div class="hello-row"><div><div class="eyebrow">TEST CONDITIONS · REFLECTION · REMEDIATION</div><h1>Exam training room 📝</h1><p class="sub">Fresh conceptual checks linked to the real topics. Show complete calculations for the independent exam problems in each lesson.</p></div><div class="illustration">✏️</div></div><div class="filters"><button class="filter-btn ${phase==='midterm'?'active':''}" data-action="practice-phase" data-id="midterm">Midterm 2 · Ch. 5–7</button><button class="filter-btn ${phase==='final'?'active':''}" data-action="practice-phase" data-id="final">Final · cumulative practice</button></div><div class="exam-brief"><div class="exam-head"><div><div class="eyebrow">${phase==='midterm'?'NOVEMBER 5 · 75-MIN EXAM':'DECEMBER 18 · 150-MIN EXAM'}</div><h2 style="margin:8px 0">${phase==='midterm'?'Midterm readiness check 🎯':'Comprehensive final readiness check 🌷'}</h2><p class="small muted" style="max-width:650px">${test.length} automatically graded multiple-choice checks. Answers stay hidden until you submit. Pair this with the worked and timed calculation problems throughout your 2-hour lessons. Official exam questions and exact scope are not available.</p><div class="chiprow">${button(submitted?'Restart quiz':'Submit & grade all questions','submit-practice',phase,submitted?'ghost':'secondary')}${button('Review 120-minute lessons','nav','lessons','ghost')}</div></div><div class="exam-score"><b>${submitted?`${correct}/${test.length}`:`${attempted}/${test.length}`}</b><small>${submitted?'correct answers':'responses saved'}</small></div></div></div><section class="card applied-paper"><div class="exam-head"><div><div class="eyebrow">APPLIED ENGINEERING MOCK · ORIGINAL QUESTIONS</div><h2 style="margin:7px 0">${phase==='midterm'?'75-mark calculation paper':'150-mark cumulative calculation paper'}</h2><p class="small muted">${D.papers[phase].length} multi-part problems · the total marks match the confirmed exam duration in minutes for realistic pacing. This is a practice assessment, NOT the professor's actual paper.</p></div>${badge(phase==='midterm'?'75 min / 75 marks':'150 min / 150 marks','peach')}</div><div class="card exam-timer-card" style="box-shadow:none;background:var(--surf2);margin:14px 0"><div><div class="small-label">OPTIONAL TIMED MOCK COUNTDOWN</div><div class="timer" id="session-timer">${phase==='midterm'?'01:15:00':'02:30:00'}</div><div class="timer-controls"><button class="button small" data-action="timer-start" data-id="practice-${phase}" id="timer-toggle">Start exam timer</button>${button('Reset','timer-reset','practice-'+phase,'ghost')}</div></div><p class="small muted" style="max-width:250px">Show complete solution steps and physical interpretation; reveal marking guidance only after attempting each problem.</p></div>${D.papers[phase].map((q,i)=>`<section class="paper-question"><div class="paper-top"><div><div class="small-label">PROBLEM ${i+1} · CHAPTER ${q.chapter}</div><h3 style="margin:7px 0 0">${esc(q.title)}</h3></div>${badge(q.marks+' marks','blue')}</div><p>${esc(q.problem)}</p><button class="solution-toggle" data-action="drill-answer">Reveal marking guidance ↓</button><div class="solution-text"><b>Worked marking guide:</b> ${esc(q.solution)}</div></section>`).join('')}</section><div class="section-heading"><h2>Quick concept checks</h2>${badge(test.length+' questions')}</div><div style="margin-top:14px">${test.map((c,i)=>`<section class="question-card"><div class="small-label">QUESTION ${i+1} OF ${test.length} · CHAPTER ${c.ch}</div><h3 style="margin:9px 0 15px">${esc(c.question)}</h3>${c.options.map((o,j)=>`<button class="quiz-opt ${submitted&&j===c.correct?'selected-correct':submitted&&j===P.exam[phase+'-'+c.id]?'selected-wrong':''}" data-action="exam-answer" data-id="${phase+'-'+c.id}" data-choice="${j}" ${submitted?'disabled':''}><span style="width:27px;font-weight:800">${'ABC'[j]}.</span>${esc(o)}${P.exam[phase+'-'+c.id]===j?'<span style="margin-left:auto;font-size:11px;font-weight:900;color:var(--primary2)">Selected</span>':''}</button>`).join('')}${submitted?`<p class="small" style="color:var(--green)"><b>Explanation:</b> ${esc(c.trap)}<br><b>Review:</b> ${esc(c.refs)}</p>`:''}</section>`).join('')}</div>`}
function pageFormulas(){let xs=D.concepts.filter(c=>!ui.formulaSearch.trim()||`${c.title} ${c.ch} ${c.formula}`.toLowerCase().includes(ui.formulaSearch.toLowerCase()));let ordered=[...xs.filter(x=>P.saved[x.id]),...xs.filter(x=>!P.saved[x.id])];return `<div class="hello-row"><div><div class="eyebrow">SAVE · RETRIEVE · APPLY</div><h1>The exam formula toolkit ∑</h1><p class="sub">${D.concepts.length} beautifully rendered formulas. Every equation includes an exam decision rule and source alignment.</p></div><div class="illustration">📐</div></div><div class="notice"><span>✎</span><div><strong>Formula discipline:</strong> First identify input data, model, independent/correlated assumptions, degrees of freedom, and required output; then substitute values with units. Confirm what tables or reference sheets your exam permits.</div></div><div class="filters"><input id="formula-search" class="search" style="width:min(100%,550px)" placeholder="⌕  Search MLE, confidence, Weibull, FORM, Monte Carlo..." value="${esc(ui.formulaSearch)}">${badge(`${xs.length} matching formulas`,'mint')}</div><div class="formula-grid">${ordered.map(c=>`<article class="formula-tile"><div class="tile-top"><span class="small-label">CHAPTER ${c.ch} · ${P.saved[c.id]?'★ SAVED':'QUICK REFERENCE'}</span>${button(P.saved[c.id]?'★':'☆','save-formula',c.id,'ghost')}</div><h3 style="margin:13px 0 2px">${esc(c.title)}</h3><div class="math">${fmtMath(c.formula)}</div><p class="small muted">${esc(c.why)}</p><div class="source-row">${button('Copy LaTeX','copy',c.id)}${button('Practice this','topic-practice',c.id,'ghost')}</div></article>`).join('')}</div>`}
const labs=[['reliability','Failure probability & beta','🎯'],['probability','Normal CDF visualizer','📈'],['hist','Histogram experiment','▥'],['ci','Confidence-interval explorer','📏'],['propagate','Uncertainty propagation','🔀'],['regression','Regression & noise','📉'],['monte','Monte Carlo convergence','🎲'],['system','Series vs parallel systems','⚙️'],['survival','Weibull life & hazard','⏳'],['likelihood','Likelihood curve','⛰️'],['bayes','Bayesian updating','🧠'],['limit','Failure surface explorer','◈'],['chisq','Chi-square fit test','🧪'],['ks','Empirical CDF / K–S','〰️'],['counts','Poisson counts','🔢'],['clt','Sampling distribution / CLT','🔔']];
function pageLab(){return `<div class="hello-row"><div><div class="eyebrow">TOUCH THE PARAMETERS · SEE THE MATH</div><h1>The interactive engineering lab 🔬</h1><p class="sub">Change an input, predict the result, then compare what actually happens. Nothing requires a server.</p></div><div class="illustration">🧪</div></div><div class="lab-layout"><aside class="card" style="padding:12px"><div class="lab-menu">${labs.map(([id,name,em])=>`<button class="lab-option ${ui.lab===id?'active':''}" data-action="lab" data-id="${id}">${em} ${esc(name)}</button>`).join('')}</div></aside><section class="card"><div class="eyebrow">LIVE EXPERIMENT</div><h2 id="lab-title" style="margin:8px 0">${esc((labs.find(x=>x[0]===ui.lab)||labs[0])[1])}</h2><p class="muted small" id="lab-instruction">Move a slider and watch the result change. Before moving it, write down your prediction.</p><div class="slider-grid" id="lab-controls"></div><div class="lab-canvas" id="lab-canvas"></div><div class="lab-result" id="lab-result"></div><div class="chiprow" style="margin-top:16px">${button('Regenerate sample ↻','reroll','', 'ghost')}${button('Reset controls','lab-reset',ui.lab,'ghost')}</div><div class="topic-title">Experiment reflection</div><p class="small muted">What parameter had the strongest impact, and why? Which underlying assumptions matter? Can you reproduce one result analytically using the formula bank?</p></section></div>`}
function pageCoverage(){let source=[['Fall 2026 course syllabus','Confirmed exam dates, durations and broad topic descriptions','https://docs.google.com/document/d/1VmjIQ0KOF4nHRLYDWUaGlrxgAjGOPJIv/edit'],['Haldar & Mahadevan textbook','Chapters 1–9, complete source table of contents and appendices','https://drive.google.com/file/d/1148vFiqdBaMrc8knX89JLGKiayerEoQp/view'],['Chapter 5-2 faculty presentation','All 43 slides, slide-by-slide coverage mapping','https://drive.google.com/file/d/1wllHplISD8jUxm7_puCKHY-l6EvmooBy/view'],['Chapter 5 Zero to Mastery teaching kit','Previous slides, tutor notes, guided workbooks and cheat sheets','https://drive.google.com/drive/folders/1Ma9WXdKS4kkG4xEdPoap4BPxnF1XswDM']];return `<div class="hello-row"><div><div class="eyebrow">AUDITABLE MATERIALS & TRANSPARENCY</div><h1>Source coverage audit 📚</h1><p class="sub">A navigable crosswalk of every textbook chapter and subsection title, plus all 43 supplied faculty slides.</p></div><div class="illustration">🔎</div></div><div class="coverage-status">✓ ${Object.values(D.toc).reduce((n,v)=>n+v.length,0)} subsection index entries and 43 faculty slides catalogued · ${D.concepts.length} original conceptual workshops · ${lessons.length} lesson plans</div><div class="notice"><span>!</span><div><strong>Honest limitations:</strong> A table-of-contents index is not a verbatim reproduction of the 321-page textbook. We supply original guided explanations and exercises across the nine chapters; not every paragraph, worked textbook example or appendix table has been reproduced. The separately assigned Chapter 6–7 faculty slide decks and the final's confirmed scope have not been provided. Reconcile later slides and teacher instructions when they arrive.</div></div><div class="section-heading"><h2>Authenticated reading sources</h2></div><div class="coverage-grid">${source.map(([name,desc,url])=>`<div class="card"><b>${esc(name)}</b><p class="small muted" style="margin:7px 0 13px">${esc(desc)}</p><a class="source-link" href="${url}" target="_blank" rel="noopener noreferrer">Open source ↗</a></div>`).join('')}</div><div class="section-heading"><h2>Chapter-by-chapter table of contents</h2>${badge('Indexed · Chapters 1–9','mint')}</div><div class="coverage-grid">${Object.entries(D.toc).map(([ch,sections])=>`<section class="toc-chapter"><h3>Chapter ${ch} · ${esc(D.chapters[ch])}</h3><p class="muted small">${D.concepts.filter(c=>c.ch==ch).length} original workshops mapped to this chapter.</p>${sections.map(([num,title])=>`<div class="toc-line"><b>${esc(num)}</b><span>${esc(title)}</span></div>`).join('')}<div style="margin-top:15px">${button('Find these lessons →','find-chapter',ch)}</div></section>`).join('')}</div><div class="section-heading"><h2>All supplied Chapter 5 faculty slides</h2></div><section class="card">${D.slides.map(([start,end,title])=>`<div class="slides-line"><b>${start===end?'Slide '+start:'Slides '+start+'–'+end}</b><span>${esc(title)}</span></div>`).join('')}<div class="notice"><span>📌</span><div>Includes the Bayesian estimation discussion on Slide 32, one-sided intervals on Slide 38, and variance confidence intervals on Slides 42–43. No slide is intentionally omitted from the index.</div></div></section><div class="section-heading"><h2>Reference appendices & exam use</h2></div><div class="card"><p>Appendix 1: Standard normal CDF · Appendix 2: Gamma function · Appendix 3: Chi-square CDF · Appendix 4: K–S critical values · Appendix 5: Student’s t CDF · Appendix 6: Gram–Schmidt orthogonalization · Conversion factors, references, and index.</p><p class="small muted">Consult the provided textbook for authoritative critical-value tables, numerical examples, and all appendices. Do not assume a particular reference sheet or calculator is allowed in the exam.</p></div>`}
function erf(x){const sign=Math.sign(x),a=Math.abs(x),t=1/(1+.3275911*a);return sign*(1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-a*a))}
function Phi(z){return .5*(1+erf(z/Math.SQRT2))}
function invPhi(p){let lo=-9,hi=9;for(let j=0;j<45;j++){let m=(lo+hi)/2;if(Phi(m)<p)lo=m;else hi=m}return (lo+hi)/2}
function npdf(x,m=0,s=1){return Math.exp(-.5*((x-m)/s)**2)/(s*Math.sqrt(2*Math.PI))}
const rf=(x,d=3)=>Number(x).toLocaleString('en-US',{maximumFractionDigits:d});
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const lcfg={
 reliability:[['rmean','Resistance mean, μR',80,180,5,130],['smean','Load mean, μS',40,140,5,85],['rsd','Resistance SD, σR',2,35,1,16],['ssd','Load SD, σS',2,35,1,18]],
 probability:[['mean','Normal mean, μ',-3,3,.5,0],['sd','Standard deviation, σ',.4,3,.1,1],['thresh','Threshold x',-4,5,.25,.5]],
 hist:[['n','Sample size',20,500,20,120],['bins','Number of bins',4,24,1,12],['shift','Mean shift',-3,3,.25,0]],
 ci:[['mean','Sample mean',40,120,2,80],['sigma','Population σ',2,24,1,12],['n','Sample size n',8,200,4,36],['confidence','Confidence',80,99,1,95]],
 propagate:[['sx','SD of X',1,14,.5,6],['sy','SD of Y',1,14,.5,8],['rho','Correlation ρ',-1,1,.05,0],['a','Y = aX + bZ, a',-3,3,.25,1]],
 regression:[['slope','True slope',-4,4,.25,2],['noise','Noise scale',0,7,.25,2],['intercept','Intercept',-4,4,.25,0]],
 monte:[['n','Trials N',100,10000,100,1500],['rmean','Resistance mean',100,170,2,130],['smean','Load mean',50,140,2,100]],
 system:[['r1','Component reliability A',.1,.999,.01,.9],['r2','Component reliability B',.1,.999,.01,.9]],
 survival:[['shape','Weibull shape, k',.5,5,.1,2],['scale','Weibull scale, η',20,160,5,100],['t','Elapsed time',0,200,5,70]],
 likelihood:[['rate','Candidate rate λ',.05,1,.01,.25],['n','Sample observations',3,24,1,8],['mean','Observed sample mean',1,12,.25,4]],
 bayes:[['prior','Prior probability',.01,.99,.01,.3],['lra','Evidence likelihood ratio',.2,12,.2,4]],
 limit:[['r','Observed resistance',25,125,5,75],['s','Observed load',25,125,5,85]],
 chisq:[['d','Mismatch per bin',0,9,1,3],['expected','Expected per bin',10,50,5,20]],
 ks:[['shift','Distribution shift',-2,2,.1,.5],['spread','Observed spread',.5,2,.1,1]],
 counts:[['lambda','Event count mean λ',.2,12,.2,3],['k','Count k',0,20,1,3]],
 clt:[['n','Contributions per sum',1,100,1,16],['sigma','Individual SD',.5,5,.5,2]]
};
let reroll=1;
function currentParams(){const cfg=lcfg[ui.lab]||lcfg.reliability;let out=ui.expParams[ui.lab]||{};for(const [id,,,,,defaultV]of cfg){if(out[id]===undefined)out[id]=defaultV}ui.expParams[ui.lab]=out;return out}
function svgLine(fn,min,max,yMin,yMax,color='#8675ec',dotted=false){let pts=[];for(let i=0;i<=180;i++){let x=min+(max-min)*i/180,y=clamp(fn(x),yMin,yMax);pts.push(`${(43+520*i/180).toFixed(2)},${(244-198*(y-yMin)/(yMax-yMin)).toFixed(2)}`)}return `<polyline points="${pts.join(' ')}" stroke="${color}" stroke-width="3.5" fill="none" ${dotted?'stroke-dasharray="7 6"':''} stroke-linejoin="round" stroke-linecap="round"/>`}
function baseChart(inner,min,max,ylabels='Probability / density'){return `<svg viewBox="0 0 602 288" role="img" aria-label="Interactive mathematical visualization"><defs><linearGradient id="plotFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#8f80ed" stop-opacity=".24"/><stop offset="1" stop-color="#8f80ed" stop-opacity="0"/></linearGradient></defs><rect x="1" y="1" width="600" height="285" rx="14" fill="transparent"/>${[0,1,2,3,4].map(i=>`<line x1="43" y1="${46+i*49.5}" x2="563" y2="${46+i*49.5}" stroke="var(--stroke)" stroke-dasharray="4 5"/>`).join('')}<line x1="43" y1="244" x2="563" y2="244" stroke="#b6b3c9"/><line x1="43" y1="46" x2="43" y2="244" stroke="#b6b3c9"/>${inner}<text x="43" y="270" fill="var(--muted)" font-size="10">${rf(min,1)}</text><text x="540" y="270" fill="var(--muted)" font-size="10">${rf(max,1)}</text><text x="54" y="33" fill="var(--muted)" font-size="11">${esc(ylabels)}</text></svg>`}
function vertical(x,min,max,color='#f2a66d'){let xp=43+520*(x-min)/(max-min);return `<line x1="${xp}" y1="46" x2="${xp}" y2="244" stroke="${color}" stroke-width="2" stroke-dasharray="6 5"/><circle cx="${xp}" cy="244" r="5" fill="${color}"/>`}
function barPlot(vals,minY,maxY){const n=vals.length;return `<svg viewBox="0 0 602 288" role="img" aria-label="Histogram"><text x="43" y="29" fill="var(--muted)" font-size="11">Counts and simulated observations</text>${[0,1,2,3,4].map(i=>`<line x1="43" y1="${46+i*49.5}" x2="563" y2="${46+i*49.5}" stroke="var(--stroke)" stroke-dasharray="4 5"/>`).join('')}${vals.map((v,i)=>{let bw=520/n-6,h=198*v/Math.max(1,maxY),x=45+i*520/n,y=244-h;return `<rect x="${x}" y="${y}" width="${bw}" height="${h}" rx="4" fill="#9c8dec"/><text x="${x+bw/2}" y="${Math.max(40,y-5)}" font-size="10" text-anchor="middle" fill="var(--muted)">${v}</text>`}).join('')}</svg>`}
function deterministicNormal(seed){let s=(seed*1664525+1013904223)>>>0;const rand=()=>{s=(s*1664525+1013904223)>>>0;return (s+.5)/4294967296};return Math.sqrt(-2*Math.log(Math.max(.0000001,rand())))*Math.cos(2*Math.PI*rand())}
function updateLabOutput(){const el=document.activeElement;const id=el?.dataset?.param;const v=el?.value;drawLab();if(id){const x=document.getElementById('param-'+id);if(x){x.focus();x.value=v;}}}
function drawLab(){if(ui.view!=='lab')return;const lab=ui.lab,cfg=lcfg[lab]||lcfg.reliability,p=currentParams();$('#lab-controls').innerHTML=cfg.map(([id,label,min,max,step,def])=>`<div class="slider-control"><label for="param-${id}">${esc(label)}<span id="value-${id}">${rf(p[id],3)}</span></label><input id="param-${id}" data-param="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${p[id]}"></div>`).join('');let svg='',result='';
if(lab==='reliability'||lab==='monte'){const m=(p.rmean??130)-(p.smean??100),s=lab==='reliability'?Math.hypot(p.rsd,p.ssd):Math.hypot(16,18),beta=m/s,fail=Phi(-beta),lo=Math.min(-4*s+m,-4*s),hi=Math.max(4*s+m,4*s);svg=baseChart(svgLine(x=>npdf(x,m,s),lo,hi,0,.05)+vertical(0,lo,hi),lo,hi,'Failure when R − S ≤ 0');result=`<b>Reliability index β = ${rf(beta)}</b> · Theoretical probability of failure = <b>${rf(100*fail,3)}%</b> · Reliability ≈ ${rf(100*(1-fail),3)}%. ${lab==='monte'?(()=>{let n=+p.n,count=0;for(let i=0;i<n;i++)if(m+s*deterministicNormal(i+reroll*17)<0)count++;return `Simulation: ${count} failures / ${n} runs = ${rf(100*count/n,3)}%.`})():`Watch the margin distribution move across the orange failure line.`}`;}
else if(lab==='probability'){const m=p.mean,s=p.sd,th=p.thresh,lo=-8,hi=8;svg=baseChart(svgLine(x=>npdf(x,m,s),lo,hi,0,.55)+vertical(th,lo,hi),lo,hi,'Normal density & marked threshold');result=`P(X ≤ ${rf(th)}) = Φ((${rf(th)}−${rf(m)})/${rf(s)}) = <b>${rf(100*Phi((th-m)/s),2)}%</b>. Increasing σ spreads the curve while preserving total area 1.`;}
else if(lab==='hist'){let a=Array.from({length:p.bins},()=>0);for(let i=0;i<p.n;i++){let v=deterministicNormal(reroll*300+i*7)+p.shift,b=Math.floor((v+5)/10*p.bins);a[clamp(b,0,p.bins-1)]++}svg=barPlot(a,0,Math.max(...a));result=`<b>${p.n} simulated normal observations</b> in ${p.bins} bins. A histogram is descriptive; a smooth shape does not prove a distribution family.`;}
else if(lab==='ci'){const z=invPhi((1+p.confidence/100)/2),E=z*p.sigma/Math.sqrt(p.n),lo=p.mean-3*p.sigma/Math.sqrt(p.n),hi=p.mean+3*p.sigma/Math.sqrt(p.n);svg=baseChart(svgLine(x=>npdf(x,p.mean,p.sigma/Math.sqrt(p.n)),lo,hi,0,.8)+vertical(p.mean-E,lo,hi)+vertical(p.mean+E,lo,hi),lo,hi,'Sampling distribution of the sample mean');result=`${p.confidence}% z interval: <b>[${rf(p.mean-E,2)}, ${rf(p.mean+E,2)}]</b>; margin = ${rf(E,3)}. Assumes known σ, independent sampling, and justified normality/large-sample approximation.`;}
else if(lab==='propagate'){const v=p.a*p.a*p.sx*p.sx+p.sy*p.sy+2*p.a*p.rho*p.sx*p.sy,sd=Math.sqrt(Math.max(0,v));svg=baseChart(svgLine(x=>npdf(x,0,Math.max(.2,sd)),-55,55,0,.3),-55,55,'Output density for Y=aX+Z');result=`Var(Y) = a²σX² + σZ² + 2aρσXσZ = <b>${rf(v)}</b>; SD = <b>${rf(sd)}</b>. Change correlation and see why assuming independence can be misleading.`;}
else if(lab==='regression'){let pts=[],lo=-4,hi=15;const n=12;for(let i=0;i<n;i++){let x=i,y=p.intercept+p.slope*x+p.noise*deterministicNormal(i+reroll*20);pts.push([x,y])}let ys=pts.map(p=>p[1]),miny=Math.min(...ys,-5),maxy=Math.max(...ys,20),rr=maxy-miny;let dots=pts.map(([x,y])=>`<circle cx="${43+520*x/11}" cy="${244-198*(y-miny)/rr}" r="5.2" fill="#e9a866" opacity=".85"/>`).join('');svg=baseChart(dots+svgLine(x=>p.intercept+p.slope*x,0,11,miny,maxy),0,11,'Noisy observations and underlying linear relation');result=`Engineering model: <b>y = ${rf(p.intercept,2)} + ${rf(p.slope,2)}x + ε</b>. Noise scale ${p.noise}. Examine whether residuals are roughly random, not just whether the line looks attractive.`;}
else if(lab==='system'){let series=p.r1*p.r2,parallel=1-(1-p.r1)*(1-p.r2);svg=`<svg viewBox="0 0 602 288" role="img" aria-label="Series versus parallel reliability"><text x="35" y="40" fill="var(--muted)" font-size="15">SERIES</text><rect x="100" y="14" width="${Math.max(1,450*series)}" height="60" rx="12" fill="#9686ed"/><text x="110" y="51" fill="white" font-size="20" font-weight="700">${rf(100*series,1)}%</text><text x="35" y="140" fill="var(--muted)" font-size="15">PARALLEL</text><rect x="100" y="114" width="${Math.max(1,450*parallel)}" height="60" rx="12" fill="#70c3a2"/><text x="110" y="153" fill="white" font-size="20" font-weight="700">${rf(100*parallel,1)}%</text><text x="100" y="239" fill="var(--muted)" font-size="12">Assumes independent components, same mission conditions.</text></svg>`;result=`Two components in series: <b>${rf(100*series,2)}%</b> mission reliability. In parallel: <b>${rf(100*parallel,2)}%</b>. Dependence/shared hazards can drastically change both.`;}
else if(lab==='survival'){let k=p.shape,eta=p.scale,x=p.t;const surv=t=>Math.exp(-((t/eta)**k));svg=baseChart(svgLine(t=>surv(t),0,200,0,1)+vertical(x,0,200),0,200,'Weibull survival S(t)');result=`S(${rf(x)}) = <b>${rf(100*surv(x),2)}%</b>; instantaneous hazard h(${rf(Math.max(.001,x))}) ≈ <b>${rf(k/eta*(Math.max(.001,x)/eta)**(k-1),5)}</b>. If k>1, hazard increases with age.`;}
else if(lab==='likelihood'){let n=p.n,mean=p.mean,opt=1/mean;const f=rate=>n*(Math.log(rate)-rate*mean+1+Math.log(mean)),min=.05,max=1;svg=baseChart(svgLine(rate=>Math.exp(clamp(f(rate),-50,0)),min,max,0,1)+vertical(p.rate,min,max),min,max,'Relative likelihood (peak normalized to 1)');result=`For exponential data, λ̂ = 1/mean = <b>${rf(opt,3)}</b>. Your candidate λ=${rf(p.rate,2)}, relative likelihood=<b>${rf(100*Math.exp(clamp(f(p.rate),-50,0)),2)}%</b> of the peak.`;}
else if(lab==='bayes'){let prior=p.prior,lr=p.lra,post=prior*lr/(prior*lr+1-prior);svg=`<svg viewBox="0 0 602 288"><text x="40" y="40" fill="var(--muted)" font-size="14">PRIOR</text><rect x="40" y="57" width="500" height="45" rx="10" fill="#eeeaf8"/><rect x="40" y="57" width="${prior*500}" height="45" rx="10" fill="#b5a5f0"/><text x="44" y="86" font-size="17" font-weight="700" fill="#382c7d">${rf(prior*100,1)}%</text><text x="40" y="150" fill="var(--muted)" font-size="14">POSTERIOR AFTER EVIDENCE</text><rect x="40" y="168" width="500" height="45" rx="10" fill="#eeeaf8"/><rect x="40" y="168" width="${post*500}" height="45" rx="10" fill="#68bea0"/><text x="44" y="196" font-size="17" font-weight="700" fill="#174934">${rf(post*100,1)}%</text></svg>`;result=`Prior P(H)=${rf(100*prior,1)}% · evidence likelihood ratio = ${rf(lr,2)}. Updated posterior = <b>${rf(post*100,2)}%</b>. Posterior odds = prior odds × likelihood ratio.`;}
else if(lab==='limit'){const g=p.r-p.s;svg=`<svg viewBox="0 0 602 288" role="img" aria-label="Resistance versus load and limit state"><rect x="45" y="20" width="235" height="235" fill="#ebf8ef" rx="8"/><path d="M45 20L280 20L45 255Z" fill="#fff0eb"/><line x1="45" y1="255" x2="280" y2="20" stroke="#f0a47e" stroke-width="3" stroke-dasharray="8 5"/><circle cx="${45+235*p.r/125}" cy="${255-235*p.s/125}" r="9" fill="#7667e9" stroke="white" stroke-width="3"/><text x="308" y="50" font-size="16" font-weight="700" fill="var(--ink)">Failure boundary: R = S</text><text x="308" y="84" font-size="14" fill="var(--muted)">Horizontal: resistance R</text><text x="308" y="112" font-size="14" fill="var(--muted)">Vertical: load S</text><text x="308" y="163" font-size="14" fill="#6bac8b">Safe zone: R > S</text><text x="308" y="197" font-size="14" fill="#d48f71">Failure: R ≤ S</text></svg>`;result=`g=R−S=<b>${g}</b>. ${g>0?'Safe by this criterion':g===0?'On the failure boundary':'Failed by this criterion'}. This diagram is deterministic; reliability adds distributions around the input point.`;}
else if(lab==='chisq'){let exp=p.expected,d=p.d,obs=[exp+d,exp-d,exp+d,exp-d],stat=4*d*d/exp;svg=barPlot(obs,0,exp+d+5);result=`Observed counts: ${obs.map(rf).join(', ')}; expected each ${exp}. χ² = 4×${d}²/${exp} = <b>${rf(stat)}</b>. For 4 bins with no fitted parameters, df=3; compare with χ² critical value for chosen α.`;}
else if(lab==='ks'){let shifted=x=>Phi((x-p.shift)/p.spread);svg=baseChart(svgLine(Phi,-3.5,3.5,0,1,'#8d7df3')+svgLine(shifted,-3.5,3.5,0,1,'#72c5a5',true),-3.5,3.5,'Theoretical (purple) vs observed (green) CDF');let mx=0;for(let i=0;i<400;i++){let x=-3.5+i*7/399;mx=Math.max(mx,Math.abs(Phi(x)-shifted(x)))}result=`Largest modeled CDF gap = <b>${rf(mx)}</b>. Real K–S is calculated from an empirical step CDF; this smooth comparison isolates how parameter shift changes the discrepancy.`;}
else if(lab==='counts'){let lambda=p.lambda,f=k=>Math.exp(-lambda)*Math.pow(lambda,k)/factorial(k),bars=Array.from({length:17},(_,i)=>f(i));svg=barPlot(bars.map(x=>+(x*100).toFixed(2)),0,Math.max(...bars)*110);result=`Poisson P(N=${p.k})=e^(−λ)λ^k/k! = <b>${rf(100*f(p.k),3)}%</b>. Mean and variance both equal λ=${rf(lambda,2)}.`;}
else if(lab==='clt'){let s=p.sigma/Math.sqrt(p.n);svg=baseChart(svgLine(x=>npdf(x,0,s),-8,8,0,Math.max(.16,1/(s*Math.sqrt(2*Math.PI))*1.1)),-8,8,'Approximate distribution of sample mean');result=`For independent samples with individual SD=${p.sigma}, SD of sample mean = <b>${rf(s,3)}</b>. The curve narrows as n increases. Exact shape depends on parent distribution and sample count.`;}
$('#lab-canvas').innerHTML=svg;$('#lab-result').innerHTML=result;
}
function factorial(n){let v=1;for(let i=2;i<=n;i++)v*=i;return v}
let timerInterval=null,activeTimer=null;
function tick(){if(!activeTimer)return;const left=Math.max(0,Math.ceil((activeTimer.ends-Date.now())/1000));let text=[Math.floor(left/3600),Math.floor((left%3600)/60),left%60].map(x=>String(x).padStart(2,'0')).join(':');const el=$('#session-timer');if(el)el.textContent=text;const t=$('#timer-toggle');if(t)t.textContent=activeTimer.paused?'Resume':'Pause';if(left<=0){clearInterval(timerInterval);activeTimer=null;toast('Two-hour session complete. Great work!')}}
function handleClick(e){let b=e.target.closest('[data-action],[data-view],[data-exam]');if(!b)return;
 if(b.dataset.view){route(b.dataset.view);return}if(b.dataset.exam){route('practice');ui.practicePhase=b.dataset.exam;render(true);return}
 let a=b.dataset.action,id=b.dataset.id;if(a==='nav'){route(id);return}if(a==='open-lesson'){route('lesson',id);return}if(a==='open-topic'){route('topic',id);return}if(a==='topic-complete'){P.topicDone[id]=!P.topicDone[id];persist();render(false);toast(P.topicDone[id]?'Topic mastered ✓':'Topic marked for revision');return}if(a==='exam'){ui.practicePhase=id;route('practice');return}if(a==='filter'){ui.filter=id;render(false);return}if(a==='chapter-filter'){ui.chapter=id;ui.search='';render(true);return}if(a==='go-ch5'){ui.chapter='5';ui.search='';ui.filter='all';route('lessons');return}if(a==='month'){ui.month=id;render(false);return}if(a==='practice-phase'){ui.practicePhase=id;render(true);return}if(a==='find-chapter'){ui.filter='all';ui.chapter=id;ui.search='';route('lessons');return}
 if(a==='toggle-reader-outline'){const aside=b.closest('.reader-rail');const open=aside?.classList.toggle('expanded');b.setAttribute('aria-expanded',String(!!open));b.textContent=open?'Hide chapter topics ▴':`Show ${aside?.querySelectorAll('.reader-rail-link').length||0} chapter topics ▾`;return}if(a==='toggle-topic'){const body=$('#body-'+id),opened=!body.classList.contains('hidden');body.classList.toggle('hidden',opened);b.setAttribute('aria-expanded',String(!opened));return}
 if(a==='jump-topic'){let el=document.getElementById(id),body=el?.querySelector('.topic-body'),head=el?.querySelector('.topic-header');if(body){body.classList.remove('hidden');head?.setAttribute('aria-expanded','true');el.scrollIntoView({behavior:'smooth',block:'start'})}return}
 if(a==='drill-answer'){const box=b.parentElement.querySelector('.solution-text');if(box){let shown=box.classList.toggle('visible');b.textContent=shown?'Hide worked solution ↑':'Reveal worked solution ↓'}return}
 if(a==='reveal'){P.reveals[id]=!P.reveals[id];persist();const box=b.parentElement.querySelector('.reveal');if(box)box.classList.toggle('open',!!P.reveals[id]);b.textContent=P.reveals[id]?'Hide worked answer':'Reveal worked answer';return}
 if(a==='quiz'){P.quiz[id]=+b.dataset.choice;persist();const quiz=b.closest('.quiz-box'),c=dict[id.split('-').slice(1).join('-')];if(quiz&&c){quiz.querySelectorAll('.quiz-opt').forEach((opt,j)=>{opt.classList.toggle('selected-correct',j===c.correct);opt.classList.toggle('selected-wrong',j===P.quiz[id]&&j!==c.correct)});let info=quiz.querySelector('.quiz-feedback');if(!info){info=document.createElement('div');info.className='quiz-feedback';quiz.append(info)}info.textContent=(P.quiz[id]===c.correct?'✓ Correct! ':'↻ Not quite. ')+c.trap;info.style.color=P.quiz[id]===c.correct?'var(--green)':'#be6559'}return}
 if(a==='save-formula'){P.saved[id]=!P.saved[id];persist();toast(P.saved[id]?'Formula saved ★':'Removed from saved formulas');if(ui.view==='formulas')render(false);else b.textContent=P.saved[id]?'★ Saved formula':'☆ Save formula';return}
 if(a==='copy'){const c=dict[id];let s=c.formula;navigator.clipboard?.writeText(s).then(()=>toast('LaTeX formula copied')).catch(()=>toast('Select and copy the rendered equation'));return}
 if(a==='topic-practice'){route('topic',id);return}
 if(a==='open-lab'){ui.lab=lcfg[id]?id:'reliability';route('lab');return}
 if(a==='lab'){ui.lab=id;render(false);return}if(a==='lab-reset'){delete ui.expParams[ui.lab];drawLab();return}if(a==='reroll'){reroll++;drawLab();toast('New random realization generated');return}
 if(a==='exam-answer'){if(P.settings['submitted-'+ui.practicePhase])return;P.exam[id]=+b.dataset.choice;persist();const card=b.closest('.question-card');card?.querySelectorAll('.quiz-opt').forEach(x=>x.querySelector('span:last-child')?.remove());render(false);return}
 if(a==='submit-practice'){if(P.settings['submitted-'+id]){D.concepts.forEach(c=>delete P.exam[id+'-'+c.id]);P.settings['submitted-'+id]=false;toast('New exam attempt started')}else{P.settings['submitted-'+id]=true;toast('Quiz graded — review the answer explanations')}persist();render(false);return}
 if(a==='timer-start'){if(activeTimer&&activeTimer.paused){activeTimer.ends=Date.now()+activeTimer.remaining*1000;activeTimer.paused=false}else if(activeTimer&&!activeTimer.paused){activeTimer.remaining=Math.max(0,Math.ceil((activeTimer.ends-Date.now())/1000));activeTimer.paused=true}else {const seconds=id==='practice-midterm'?75*60:id==='practice-final'?150*60:120*60;activeTimer={id,ends:Date.now()+seconds*1000,remaining:seconds,paused:false}};clearInterval(timerInterval);timerInterval=setInterval(tick,500);tick();return}
 if(a==='timer-reset'){activeTimer=null;clearInterval(timerInterval);let el=$('#session-timer');if(el)el.textContent=id==='practice-midterm'?'01:15:00':id==='practice-final'?'02:30:00':'02:00:00';let t=$('#timer-toggle');if(t)t.textContent='Start';return}
 if(a==='print'){window.print();return}
}
document.addEventListener('click',handleClick);
document.addEventListener('change',e=>{const b=e.target;if(b.matches('[data-check]')){P.checks[b.dataset.check]=b.checked;persist();let l=D.lessons.find(x=>x.id===ui.lesson);if(l){const tag=b.closest('.card');let title=tag?.querySelector('p.small');if(title)title.textContent=dayCheck(l)+' of 7 completed';const track=tag?.querySelector('.progress-fill');if(track)track.style.width=pct(dayCheck(l),7)+'%'}toast(b.checked?'Checklist step complete ✓':'Checklist updated')}});
document.addEventListener('input',e=>{const b=e.target;if(b.dataset.param){const p=currentParams();p[b.dataset.param]=+b.value;$('#value-'+b.dataset.param).textContent=rf(+b.value,3);updateLabOutput();return}if(b.dataset.note){P.notes[b.dataset.note]=b.value;persist();return}if(b.id==='lesson-search'||b.id==='formula-search'){let prop=b.id==='lesson-search'?'search':'formulaSearch';ui[prop]=b.value;const pos=b.selectionStart;render(false);const field=document.getElementById(b.id);field?.focus();field?.setSelectionRange(pos,pos);return}});
$('#menu-btn').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#mobile-overlay').classList.add('open')});$('#mobile-overlay').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#mobile-overlay').classList.remove('open')});
$('#theme-btn').addEventListener('click',()=>{document.body.classList.toggle('dark');P.settings.dark=document.body.classList.contains('dark');persist()});
$('#export-btn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({app:'Reliability Studio CE6300',version:1,savedAt:new Date().toISOString(),progress:P},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kanu-ce6300-progress-backup.json';a.click();URL.revokeObjectURL(url);toast('Progress backup exported')});
$('#import-btn').addEventListener('click',()=>$('#import-file').click());$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(obj.app!=='Reliability Studio CE6300'||!obj.progress)throw Error('Not a Reliability Studio backup');for(const k of ['checks','quiz','notes','reveals','saved','exam','settings','topicDone'])if(obj.progress[k]&&typeof obj.progress[k]==='object')P[k]=obj.progress[k];persist();toast('Study progress restored');render(false)}catch(e){toast('Could not import: '+e.message)}});
window.addEventListener('popstate',()=>{const [v,id]=(location.hash||'#dashboard').slice(1).split('/');ui.view=['dashboard','lessons','lesson','topic','review','planner','practice','formulas','lab','coverage'].includes(v)?v:'dashboard';ui.lesson=id||null;if(ui.view==='topic'&&dict[id])ui.chapter=String(dict[id].ch);render(true)});
if(P.settings.dark)document.body.classList.add('dark');
let hash=(location.hash||'#dashboard').slice(1).split('/');if(['dashboard','lessons','lesson','topic','review','planner','practice','formulas','lab','coverage'].includes(hash[0])){ui.view=hash[0];ui.lesson=hash[1]||null;if(ui.view==='topic'&&dict[ui.lesson])ui.chapter=String(dict[ui.lesson].ch)}else ui.view='dashboard';render(false);
})();
